// Domain 3 — Infrastructure. Original flashcards. One array for the whole domain: each topic's writer appends a block under its own heading comment; ids are assigned in order (d3-f001 onward).
// 3.1: facts checked against 802.1D/802.1Q cost tables, 802.1s and 802.1AX summaries and the IOS XE 17.18.1 YANG models; Cisco-specific details marked in REVIEW-TODO.md.
// 3.2: facts checked against RFC 7868, 2328, 5340, 3101, 4271 and the IOS XE 17.18.1 YANG models; Cisco-specific details marked in REVIEW-TODO.md.
// 3.3: facts checked against RFC 5905, 2281, 9568, 1112, 2236, 3376/9776, 4607, 5015, 3618, the IANA registries, an IEEE 1588 summary and the IOS XE 17.18.1 YANG models; Cisco-specific details marked in REVIEW-TODO.md.
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  // 3.1 Layer 2
  c('3.1', 'DTP mode combinations that do NOT form a trunk?', 'auto + auto; any dynamic mode + access; any dynamic mode facing `trunk` + `nonegotiate`. Catalyst 9000 ports default to dynamic auto.'),
  c('3.1', 'What does `switchport nonegotiate` do?', 'Stops DTP on a trunk or access port. The peer must be configured statically; a dynamic peer facing it stays access.'),
  c('3.1', 'The four sections of `show interfaces trunk`?', 'Mode/encapsulation/status/native VLAN; VLANs allowed; allowed and active (VLAN exists locally); forwarding and not pruned (not STP-blocked or VTP-pruned).'),
  c('3.1', 'Native VLAN mismatch symptoms?', '`%CDP-4-NATIVE_VLAN_MISMATCH`; PVST+ blocks the port in both VLANs (`*PVID_Inc`, `BLOCK_PVID_LOCAL/PEER`); otherwise the two VLANs merge.'),
  c('3.1', '`switchport trunk allowed vlan 40` vs `... add 40`?', 'Without `add` the list is replaced by VLAN 40 only. Use `add`, `remove`, `except`, `all` on live trunks.'),
  c('3.1', 'EtherChannel modes that bundle?', 'LACP: active+active, active+passive. PAgP: desirable+desirable, desirable+auto. Static: on+on. Never mixed; passive+passive and auto+auto never form.'),
  c('3.1', 'What must match on EtherChannel members?', 'Speed, duplex, switchport mode (L2/L3, access/trunk), access VLAN or native and allowed VLANs. Different STP costs are allowed. Mismatch = suspended `(s)`.'),
  c('3.1', 'LACP defaults and limits?', 'System and port priority 32768 (lower wins); slow 30 s / 90 s timeout, fast 1 s / 3 s; up to 8 active + 8 hot-standby; `lacp max-bundle` caps active.'),
  c('3.1', '`show etherchannel summary` key flags?', 'Channel: `SU` L2 up, `RU` L3 up, `SD` down, `M` min links not met. Member: `P` bundled, `I` stand-alone, `s` suspended, `H` hot standby, `D` down.'),
  c('3.1', 'Build a Layer 3 port channel?', 'On members: `no switchport` then `channel-group N mode active`; then `interface Port-channel N` and `ip address ...`.'),
  c('3.1', 'Bridge ID format?', '4-bit priority (0–61440, steps of 4096, default 32768) + 12-bit extended system ID (VLAN or MST instance) + 48-bit MAC. Shown priority = priority + VLAN.'),
  c('3.1', 'Root port tie-breakers in order?', 'Lowest root path cost, lowest sender bridge ID, lowest sender port priority, lowest sender port number.'),
  c('3.1', 'STP short and long path costs?', 'Short: 10 Mb 100, 100 Mb 19, 1 Gb 4, 10 Gb 2. Long: 2,000,000 / 200,000 / 20,000 / 2,000; 100 Gb 200. MST always long.'),
  c('3.1', '802.1D timers and convergence?', 'Hello 2 s, max age 20 s, forward delay 15 s. 30 s from link-up to forwarding; up to 50 s for indirect failures.'),
  c('3.1', 'RSTP port roles and states?', 'Roles: root, designated, alternate (backup root port), backup (same shared segment), disabled. States: discarding, learning, forwarding.'),
  c('3.1', 'RSTP proposal/agreement steps?', 'Upstream proposes; downstream picks root port, syncs (blocks non-edge designated ports), agrees; upstream forwards; repeat downstream. Point-to-point links only.'),
  c('3.1', 'What defines an MST region?', 'Same name, revision and VLAN-to-instance map (carried as an HMAC-MD5 digest). Any difference = boundary. Max hops default 20.'),
  c('3.1', 'IST, MSTI, CST, CIST?', 'IST: instance 0 in a region, unmapped VLANs, sends the BPDUs. MSTI: instances 1+, region only. CST: tree between regions. CIST: IST + CST.'),
  c('3.1', 'Root guard vs loop guard?', 'Root guard: superior BPDU on a designated port = root-inconsistent. Loop guard: BPDUs stop on root/alternate port = loop-inconsistent. Both block and auto-recover.'),
  c('3.1', 'BPDU filter: interface vs global?', 'Interface `spanning-tree bpdufilter enable`: no BPDUs sent, received ignored (STP off). Global `portfast bpdufilter default`: PortFast ports only; a received BPDU returns the port to normal STP.'),
  c('3.1', 'UDLD normal vs aggressive?', 'Normal: err-disables only on positive one-way or miswire detection. Aggressive: also when messages stop on an up link. Global commands cover fibre only; 15 s messages.'),
  c('3.1', 'Err-disable recovery?', 'Manual: `shutdown` / `no shutdown`. Automatic: `errdisable recovery cause <cause>` (off by default) and `errdisable recovery interval` (default 300 s). Check `show errdisable recovery`.'),
  // 3.2 Layer 3
  c('3.2', 'EIGRP vs OSPF: protocol numbers, multicast, timers?', 'EIGRP: IP 88, 224.0.0.10, hello 5 s / hold 15 s on fast links. OSPF: IP 89, 224.0.0.5 and 224.0.0.6, hello 10 s / dead 40 s on broadcast and point-to-point.'),
  c('3.2', 'EIGRP feasibility condition?', "A neighbor's reported distance must be strictly less than this router's feasible distance. Such a neighbor is a feasible successor: a loop-free backup used instantly without queries."),
  c('3.2', 'Classic EIGRP metric with default K values?', 'K1 = K3 = 1, K2 = K4 = K5 = 0: 256 x (10^7 / minimum bandwidth in kbps + sum of delays in tens of µs).'),
  c('3.2', 'EIGRP wide metrics?', 'Named mode (`router eigrp NAME`): 64-bit metric, delay in picoseconds, scale 65,536, so links above 1 Gbps differ. Divided by `metric rib-scale` (default 128) for the RIB.'),
  c('3.2', 'OSPF cost formula and default?', 'Reference bandwidth / interface bandwidth, minimum 1. Default reference 100 Mbps, so 100 Mb, 1 Gb and 10 Gb all cost 1. Fix with `auto-cost reference-bandwidth` (Mbps) on every router.'),
  c('3.2', 'Unequal-cost load balancing?', 'EIGRP only: `variance N` (default 1) installs feasible successors with metric below N x FD. Both protocols: `maximum-paths` (default 4) for equal cost.'),
  c('3.2', 'Default administrative distances?', 'Connected 0, static 1, EIGRP summary 5, eBGP 20, EIGRP internal 90, OSPF 110, IS-IS 115, RIP 120, EIGRP external 170, iBGP 200.'),
  c('3.2', 'OSPF area types and the LSAs they block?', 'Stub: no 4/5, default injected. Totally stubby: also only a default type 3. NSSA: no 5, type 7 from a local ASBR. Totally NSSA: NSSA plus only a default type 3.'),
  c('3.2', 'OSPF neighbor states?', 'Down, (Attempt on NBMA), Init, 2-Way, ExStart, Exchange, Loading, Full. Stuck in ExStart/Exchange: MTU mismatch. 2-Way between DROTHERs is normal.'),
  c('3.2', 'OSPF adjacency must-match list?', 'Area ID, subnet and mask (not on point-to-point), hello and dead intervals, authentication, stub/NSSA flags, unique router IDs, IP MTU. Process ID and cost need not match.'),
  c('3.2', 'OSPF router ID and DR election?', 'RID: `router-id`, else highest up loopback, else highest up interface. DR: highest priority (default 1, 0 = never), then highest RID. Not preemptive.'),
  c('3.2', 'OSPFv2 LSA types 1 to 5 and 7?', '1 router, 2 network (DR), 3 summary (ABR, inter-area prefix), 4 ASBR summary (ABR), 5 AS external (ASBR), 7 NSSA external (ASBR in an NSSA, translated to 5 by the ABR).'),
  c('3.2', 'E1 vs E2 routes?', 'E2 (default): seed metric only (20 by default; 1 for BGP and a default route), constant across the domain. E1: seed plus internal cost to the ASBR. E1 preferred over E2.'),
  c('3.2', 'Summarize in OSPF?', 'Internal routes on the ABR: `area N range ADDRESS MASK`. External routes on the ASBR: `summary-address ADDRESS MASK`. Both install a Null0 discard route.'),
  c('3.2', 'OSPFv3 new LSAs?', 'Link LSA (0x0008, link scope): link-local address and link prefixes. Intra-Area-Prefix LSA (0x2009): prefixes, since router and network LSAs no longer carry any.'),
  c('3.2', 'BGP neighbor states and timers?', 'Idle, Connect, Active, OpenSent, OpenConfirm, Established. TCP 179. Cisco keepalive 60 s, hold 180 s. Stuck in Active: TCP not completing.'),
  c('3.2', 'BGP best-path order?', 'Weight, local preference, locally originated, AS_PATH, origin, MED, eBGP over iBGP, IGP metric to next hop, oldest eBGP, router ID, cluster list, neighbor address.'),
  c('3.2', 'PBR set ip next-hop vs set ip default next-hop?', '`set ip next-hop`: before the routing table, overrides it. `set ip default next-hop`: only when there is no explicit route. Apply with `ip policy route-map` on the ingress interface.'),
  // 3.3 IP services
  c('3.3', 'NTP stratum values?', '1 = attached to a reference clock (GPS, atomic); 2–15 = synchronized over NTP, one more than its source; 16 = unsynchronized. `ntp master` defaults to stratum 8. UDP 123.'),
  c('3.3', '`show ntp associations` markers?', '`*` system peer (synchronized to), `+` candidate, `#` selected, `-` outlier, `x` falseticker, `~` configured.'),
  c('3.3', 'How do you read NTP reach?', 'Octal 8-bit shift register, newest poll in the lowest bit. 377 = last eight answered; 376 = newest failed; 17 = only four answered (new association); 0 = never.'),
  c('3.3', 'NTP authentication on the client?', '`ntp authentication-key N md5 KEY`, `ntp authenticate`, `ntp trusted-key N`, `ntp server ADDRESS key N`. The server needs the same key to sign replies. Missing trusted-key = never synchronizes.'),
  c('3.3', '`ntp access-group` types?', '`peer` (requests, queries, may synchronize to the source) > `serve` (requests and queries) > `serve-only` (requests) > `query-only` (control queries only).'),
  c('3.3', 'PTP BMCA order?', 'Lowest wins: priority1 (default 128), clockClass, clockAccuracy, offsetScaledLogVariance, priority2 (default 128), clockIdentity.'),
  c('3.3', 'PTP boundary vs transparent clock?', 'Boundary: synchronizes on one SLAVE port and is master on its other ports. Transparent: does not synchronize; adds its residence time to a correction field (E2E or P2P).'),
  c('3.3', 'PTP messages and transport?', 'Announce (BMCA), Sync, Follow_Up, Delay_Req, Delay_Resp; Pdelay for per-link delay. Ethernet 0x88F7, or UDP 319 (event) and 320 (general).'),
  c('3.3', 'The four NAT address terms?', 'Inside local: inside host\'s real address. Inside global: how it appears outside. Outside local: outside host as seen inside. Outside global: outside host\'s real address.'),
  c('3.3', 'NAT and routing order?', 'Inside to outside: routing, then NAT. Outside to inside: NAT, then routing. An inbound ACL on the outside interface must use inside global addresses.'),
  c('3.3', 'Dynamic NAT vs PAT command?', '`ip nat inside source list ACL pool NAME` = one pool address per host. Add `overload` (pool or `interface IF overload`) for PAT. Clear old entries with `clear ip nat translation *`.'),
  c('3.3', 'HSRP v1 vs v2?', 'v1: groups 0–255, 224.0.0.2, `0000.0c07.acXX`. v2: groups 0–4095, 224.0.0.102, `0000.0c9f.fXXX`, IPv6 support. Both UDP 1985; they do not interoperate.'),
  c('3.3', 'HSRP defaults and states?', 'Priority 100, highest priority then highest IP, no preemption, hello 3 s, hold 10 s. States: Initial, Learn, Listen, Speak, Standby, Active.'),
  c('3.3', 'VRRP key facts?', 'IP protocol 112, 224.0.0.18 / FF02::12, VRID 1–255, MAC `0000.5e00.01XX` (IPv4) / `0000.5e00.02XX` (IPv6), priority 100 (255 = owner), preempt on, advert 1 s, no authentication in v3.'),
  c('3.3', 'VRRP master-down interval?', '3 x advertisement interval + skew, skew = (256 − own priority) / 256 x interval. Priority 100 at 1 s: 3.609 s.'),
  c('3.3', 'Multicast IP to MAC mapping?', '01-00-5E + low 23 bits of the group. Five bits are lost, so 32 groups share one MAC. 239.130.5.10 = `0100.5e02.050a`.'),
  c('3.3', 'IGMPv2 vs IGMPv3?', 'v2: general and group-specific queries, reports, Leave to 224.0.0.2, querier = lowest IP. v3: INCLUDE/EXCLUDE source lists, reports to 224.0.0.22; needed for SSM.'),
  c('3.3', 'PIM-SM vs SSM vs bidir?', 'SM: shared tree from the RP, Register/Register-Stop, SPT switchover. SSM: 232/8, IGMPv3, (S,G) only, no RP. Bidir: shared tree only, DF per link, no (S,G).'),
  c('3.3', 'MSDP and Anycast RP?', 'MSDP: RPs exchange Source-Active (S,G, RP) messages over TCP 639 to link PIM-SM domains. Anycast RP: several RPs share one address and peer with MSDP.'),
];
